import React from 'react';
import { Audio, interpolate, Sequence, staticFile } from 'remotion';

/**
 * The episode's soundtrack: one ambience bed, four chapter voiceovers, four event sounds.
 *
 * Both halves are generated by the scripts in `studio/scripts/`:
 *
 * * `tts.py` → `ch{1..4}-vo.wav` via Kokoro, an open-source neural TTS model (Apache-2.0) on ONNX
 *   Runtime. Lines live in `scripts/narration.json`.
 * * `sfx.py` → `ambience.wav` and the four event stings, synthesised from noise and oscillators so the
 *   bed is reproducible and licence-free.
 *
 * The generated WAVs are committed, so rendering needs neither Python nor a model download.
 *
 * `VOICEOVER[].frames` is the clip length rounded to frames at 30 fps. It is used only for ducking, so
 * a frame of drift is inaudible — but if you re-render a clip with different text, update the length
 * (or the ambience will un-duck slightly early or late).
 */

const CHAPTER = 400;

/** Voiceover starts a few frames into each chapter, after the chapter dip has opened up. */
const VO_OFFSET = 12;

type VoiceCue = { id: string; from: number; frames: number };

const VOICEOVER: VoiceCue[] = [
  { id: 'ch1', from: 0 * CHAPTER + VO_OFFSET, frames: 188 },
  { id: 'ch2', from: 1 * CHAPTER + VO_OFFSET, frames: 201 },
  { id: 'ch3', from: 2 * CHAPTER + VO_OFFSET, frames: 147 },
  { id: 'ch4', from: 3 * CHAPTER + VO_OFFSET, frames: 226 },
];

type EventCue = { id: string; file: string; from: number; frames: number; volume: number };

/** Placed against the scene constants: DeskScene POP = 110, the crack reveal at 826, the alert ramp at 1240. */
const EVENTS: EventCue[] = [
  { id: 'ticks', file: 'ch1-ticks.wav', from: 0, frames: 114, volume: 0.7 },
  { id: 'pop', file: 'ch1-pop.wav', from: 110, frames: 30, volume: 1 },
  { id: 'release', file: 'ch2-release.wav', from: 386, frames: 108, volume: 0.9 },
  { id: 'crack', file: 'ch3-crack.wav', from: 826, frames: 60, volume: 0.85 },
  { id: 'alarm', file: 'ch4-alarm.wav', from: 1236, frames: 180, volume: 0.5 },
];

const AMBIENCE_VOLUME = 0.55;

/**
 * How far the bed is pulled down for narration: 1 when nobody is speaking, `DUCK` under a line, with a
 * short ramp on each side so the level change never clicks.
 */
const DUCK = 0.4;

const ducked = (frame: number): number =>
  VOICEOVER.reduce((factor, cue) => {
    const end = cue.from + cue.frames;
    const level = interpolate(frame, [cue.from - 10, cue.from + 4, end - 2, end + 22], [1, DUCK, DUCK, 1], {
      extrapolateLeft: 'clamp',
      extrapolateRight: 'clamp',
    });
    return Math.min(factor, level);
  }, 1);

export const EpisodeAudio: React.FC = () => {
  return (
    <>
      <Audio src={staticFile('audio/ambience.wav')} volume={(frame) => AMBIENCE_VOLUME * ducked(frame)} />

      {EVENTS.map((event) => (
        <Sequence key={event.id} from={event.from} durationInFrames={event.frames} name={`sfx · ${event.id}`}>
          <Audio src={staticFile(`audio/${event.file}`)} volume={event.volume} />
        </Sequence>
      ))}

      {VOICEOVER.map((cue) => (
        <Sequence key={cue.id} from={cue.from} durationInFrames={cue.frames} name={`vo · ${cue.id}`}>
          <Audio
            src={staticFile(`audio/${cue.id}-vo.wav`)}
            volume={(frame) => interpolate(frame, [0, 5, cue.frames - 8, cue.frames], [0, 1, 1, 0], {
              extrapolateLeft: 'clamp',
              extrapolateRight: 'clamp',
            })}
          />
        </Sequence>
      ))}
    </>
  );
};
